import { USERS, PASSWORD, expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs, playwright }) => {
    // Arrange: a vendor with the same name already exists in another tenant
    const name = uniqueName("Acme Freight");
    const other = await apiAs("otherTenant");
    const seeded = await other.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    expect(seeded.status(), await seeded.text()).toBe(201);

    // Act: the signed-in Northwind member creates a vendor with that name
    const member = await apiAs("member");
    const response = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    expect(response.status(), await response.text()).toBe(201);
    const created = await response.json();
    expect(created.name).toBe(name);
    expect(created.id).not.toBe((await seeded.json()).id);
  });
});
